from . import point as pt

POINTS = [
pt('A1', 'be', ('Le verbe « be » au présent',
 "« Be » (être) a trois formes au présent : I am, he / she / it is, you / we / they are. À l'oral on contracte : I'm, you're, he's, we're, they're.\nNégation : on ajoute « not » (is not = isn't, are not = aren't). Question : on inverse le verbe et le sujet (Are you ready?).\nAttention : l'anglais emploie « be » pour l'âge, la faim, le froid : I am twenty, I am hungry, I am cold."),
 ('The verb “be” in the present',
 "“Be” has three present forms: I am, he / she / it is, you / we / they are. In speech they contract: I'm, you're, he's, we're, they're.\nNegative: add “not” (is not = isn't, are not = aren't). Question: swap verb and subject (Are you ready?).\nEnglish uses “be” for age, hunger and cold: I am twenty, I am hungry, I am cold."),
 [("I am a student.", "Je suis étudiant.", "I am a student."), ("She isn't at home.", "Elle n'est pas à la maison.", "She isn't at home."), ("Are they your friends?", "Est-ce que ce sont tes amis ?", "Are they your friends?")],
 r"\b(am|is|are)\b", ['am', 'is', 'are']),
pt('A1', 'articles', ('Les articles : a, an, the',
 "« A » devant un son de consonne (a book, a university), « an » devant un son de voyelle (an apple, an hour). Ils signifient « un, une » et ne s'emploient qu'au singulier.\n« The » (le, la, les) ne change jamais. On l'emploie pour ce qui est connu ou déjà mentionné.\nPas d'article pour parler des choses en général : I like music. Dogs are friendly."),
 ('Articles: a, an, the',
 "Use “a” before a consonant sound (a book, a university) and “an” before a vowel sound (an apple, an hour). They are only used in the singular.\n“The” never changes. Use it for something known or already mentioned.\nNo article when speaking in general: I like music. Dogs are friendly."),
 [("I have a dog and an umbrella.", "J'ai un chien et un parapluie.", "I have a dog and an umbrella."), ("The dog is in the garden.", "Le chien est dans le jardin.", "The dog is in the garden."), ("I love coffee.", "J'adore le café.", "I love coffee.")],
 r"\b(a|an|the)\b", ['a', 'an', 'the']),
pt('A1', 'plural', ('Le pluriel des noms',
 "On ajoute -s : book → books. Après -s, -x, -ch, -sh, on ajoute -es : box → boxes. Consonne + y → -ies : city → cities. -f / -fe → -ves : knife → knives.\nQuelques pluriels irréguliers : man → men, woman → women, child → children, foot → feet, tooth → teeth, person → people.\nL'adjectif ne prend jamais de -s : two big houses."),
 ('Plural nouns',
 "Add -s: book → books. After -s, -x, -ch, -sh add -es: box → boxes. Consonant + y → -ies: city → cities. -f / -fe → -ves: knife → knives.\nSome irregular plurals: man → men, woman → women, child → children, foot → feet, tooth → teeth, person → people.\nAdjectives never take -s: two big houses."),
 [("Two children are playing.", "Deux enfants jouent.", "Two children are playing."), ("I bought three boxes.", "J'ai acheté trois boîtes.", "I bought three boxes.")],
 r"\b(men|women|children|people|feet|teeth)\b", ['men', 'women', 'children', 'people', 'feet', 'teeth']),
pt('A1', 'present-simple', ('Le présent simple',
 "Il exprime les habitudes et les faits généraux. Le verbe ne change qu'à la 3e personne du singulier, où il prend -s : I work, she works (go → goes, study → studies, have → has).\nNégation avec do / does + not : I don't work, she doesn't work (le verbe perd alors son -s).\nQuestion : Do you work? Does she work?"),
 ('The present simple',
 "It expresses habits and general facts. The verb only changes in the third person singular, which takes -s: I work, she works (go → goes, study → studies, have → has).\nNegative with do / does + not: I don't work, she doesn't work (the verb loses its -s).\nQuestion: Do you work? Does she work?"),
 [("He works in a bank.", "Il travaille dans une banque.", "He works in a bank."), ("I don't speak Chinese.", "Je ne parle pas chinois.", "I don't speak Chinese."), ("Does she live here?", "Est-ce qu'elle habite ici ?", "Does she live here?")],
 r"\b(do|does|don't|doesn't)\b", ['do', 'does', "don't", "doesn't"]),
pt('A1', 'possessives', ('Pronoms et possessifs',
 "Sujets : I, you, he, she, it, we, they. Compléments : me, you, him, her, it, us, them.\nPossessifs : my, your, his, her, its, our, their. Ils s'accordent avec le possesseur, pas avec la chose possédée : his sister = la sœur de lui, her brother = le frère d'elle.\nPossession avec 's : Tom's car (la voiture de Tom)."),
 ('Pronouns and possessives',
 "Subjects: I, you, he, she, it, we, they. Objects: me, you, him, her, it, us, them.\nPossessives: my, your, his, her, its, our, their. They agree with the owner, not with the thing owned: his sister, her brother.\nPossession with 's: Tom's car."),
 [("This is my brother and his wife.", "Voici mon frère et sa femme.", "This is my brother and his wife."), ("Give it to them.", "Donne-le-leur.", "Give it to them.")],
 r"\b(my|your|his|her|our|their)\b", ['my', 'your', 'his', 'her', 'our', 'their']),
pt('A1', 'there-is', ('There is, there are',
 "« There is » + singulier, « there are » + pluriel : il y a. Négation : there isn't / there aren't. Question : Is there…? Are there…?\nAu passé : there was / there were."),
 ('There is, there are',
 "“There is” + singular, “there are” + plural. Negative: there isn't / there aren't. Question: Is there…? Are there…?\nPast: there was / there were."),
 [("There is a cat on the roof.", "Il y a un chat sur le toit.", "There is a cat on the roof."), ("Are there any questions?", "Y a-t-il des questions ?", "Are there any questions?")],
 r"\b[Tt]here (is|are|was|were)\b", ['is', 'are', 'was', 'were']),
pt('A1', 'can', ('Can : pouvoir, savoir faire',
 "« Can » est suivi du verbe sans « to » et ne prend jamais de -s : she can swim. Négation : cannot / can't. Question : Can you help me?\nPassé : could."),
 ('Can: ability and permission',
 "“Can” is followed by the bare verb and never takes -s: she can swim. Negative: cannot / can't. Question: Can you help me?\nPast: could."),
 [("I can speak English.", "Je sais parler anglais.", "I can speak English."), ("She can't come today.", "Elle ne peut pas venir aujourd'hui.", "She can't come today.")],
 r"\b(can|can't|cannot|could|couldn't)\b", ['can', "can't", 'could', "couldn't"]),
pt('A1', 'prepositions', ('Prépositions : in, on, at',
 "Lieu : « in » dans un espace (in the kitchen, in France), « on » sur une surface (on the table), « at » à un point précis (at the station, at home).\nTemps : « in » pour les mois, années, saisons (in May, in 2020), « on » pour les jours et dates (on Monday), « at » pour les heures (at six o'clock) et at night."),
 ('Prepositions: in, on, at',
 "Place: “in” for an enclosed space (in the kitchen, in France), “on” for a surface (on the table), “at” for a point (at the station, at home).\nTime: “in” for months, years and seasons (in May, in 2020), “on” for days and dates (on Monday), “at” for clock times (at six o'clock) and at night."),
 [("The keys are on the table.", "Les clés sont sur la table.", "The keys are on the table."), ("I was born in July.", "Je suis né en juillet.", "I was born in July."), ("See you at five.", "À cinq heures.", "See you at five.")],
 r"\b(in|on|at)\b", ['in', 'on', 'at']),
pt('A2', 'present-continuous', ('Le présent continu',
 "be + verbe en -ing : action en cours au moment où l'on parle. I am reading, she is sleeping, they are working.\nOrthographe : make → making, run → running.\nIl sert aussi pour un projet proche : I'm leaving tomorrow.\nLes verbes d'état (know, like, want, need) ne se mettent pas à cette forme."),
 ('The present continuous',
 "be + verb-ing: an action in progress now. I am reading, she is sleeping, they are working.\nSpelling: make → making, run → running.\nAlso used for near-future plans: I'm leaving tomorrow.\nState verbs (know, like, want, need) are not used in this form."),
 [("What are you doing?", "Qu'est-ce que tu fais ?", "What are you doing?"), ("It is raining.", "Il pleut.", "It is raining.")],
 r"\b(?:am|is|are|'m|'s|'re) (\w+ing)\b", None),
pt('A2', 'past-simple', ('Le prétérit (past simple)',
 "Action terminée dans le passé. Verbes réguliers : + -ed (worked, played, studied). Beaucoup de verbes courants sont irréguliers : go → went, have → had, see → saw, do → did, take → took, come → came.\n« Be » : was (I, he, she, it), were (you, we, they).\nNégation et question avec did : I didn't go. Did you see it? (le verbe reste à la base)."),
 ('The past simple',
 "A finished action in the past. Regular verbs add -ed (worked, played, studied). Many common verbs are irregular: go → went, have → had, see → saw, do → did, take → took, come → came.\n“Be”: was (I, he, she, it), were (you, we, they).\nNegative and question with did: I didn't go. Did you see it? (the main verb stays in its base form)."),
 [("I went to London last year.", "Je suis allé à Londres l'an dernier.", "I went to London last year."), ("She didn't call me.", "Elle ne m'a pas appelé.", "She didn't call me.")],
 r"\b(was|were|did|didn't|went|had|saw|took|came)\b", ['was', 'were', 'did', "didn't", 'went', 'had', 'saw', 'took', 'came']),
pt('A2', 'future', ('Le futur : will et be going to',
 "« Will » + verbe : décision prise sur le moment, prédiction, promesse (I'll help you). Négation : won't.\n« Be going to » + verbe : intention déjà décidée, ou événement qu'on voit venir (I'm going to buy a car. It's going to rain)."),
 ('The future: will and be going to',
 "“Will” + verb: a decision made now, a prediction, a promise (I'll help you). Negative: won't.\n“Be going to” + verb: an intention already decided, or something you can see coming (I'm going to buy a car. It's going to rain)."),
 [("I will call you tomorrow.", "Je t'appellerai demain.", "I will call you tomorrow."), ("We are going to move.", "Nous allons déménager.", "We are going to move.")],
 r"\b(will|won't|going to)\b", ['will', "won't", 'going to']),
pt('A2', 'comparatives', ('Comparatif et superlatif',
 "Adjectifs courts : -er … than, the -est (tall → taller than, the tallest ; big → bigger ; happy → happier).\nAdjectifs longs : more … than, the most … (more expensive, the most beautiful).\nIrréguliers : good → better → the best ; bad → worse → the worst ; far → farther.\nÉgalité : as … as (as tall as)."),
 ('Comparatives and superlatives',
 "Short adjectives: -er … than, the -est (tall → taller than, the tallest; big → bigger; happy → happier).\nLong adjectives: more … than, the most … (more expensive, the most beautiful).\nIrregular: good → better → the best; bad → worse → the worst; far → farther.\nEquality: as … as (as tall as)."),
 [("She is older than me.", "Elle est plus âgée que moi.", "She is older than me."), ("This is the best film of the year.", "C'est le meilleur film de l'année.", "This is the best film of the year.")],
 r"\b(better|worse|best|worst|more|most)\b", ['better', 'worse', 'best', 'worst', 'more', 'most']),
pt('A2', 'some-any', ('Some, any, much, many',
 "« Some » dans les phrases affirmatives (I have some money), « any » dans les négations et les questions (I don't have any money. Do you have any money?).\n« Much » avec les indénombrables (much water), « many » avec les dénombrables (many books), « a lot of » avec les deux.\nA few (quelques, dénombrable), a little (un peu, indénombrable)."),
 ('Some, any, much, many',
 "“Some” in affirmative sentences (I have some money), “any” in negatives and questions (I don't have any money. Do you have any money?).\n“Much” with uncountables (much water), “many” with countables (many books), “a lot of” with both.\nA few (countable), a little (uncountable)."),
 [("Would you like some tea?", "Voulez-vous du thé ?", "Would you like some tea?"), ("There aren't many people.", "Il n'y a pas beaucoup de monde.", "There aren't many people.")],
 r"\b(some|any|much|many)\b", ['some', 'any', 'much', 'many']),
pt('B1', 'present-perfect', ('Le present perfect',
 "have / has + participe passé (worked, seen, been, done). Il relie le passé au présent : expérience (I have been to Japan), action récente dont le résultat compte (I've lost my keys), situation qui dure encore avec for / since (I have lived here for ten years / since 2015).\nAvec une date passée précise (yesterday, in 2010), on emploie le prétérit, pas le present perfect."),
 ('The present perfect',
 "have / has + past participle (worked, seen, been, done). It links past and present: experience (I have been to Japan), a recent action whose result matters (I've lost my keys), a situation still going on with for / since (I have lived here for ten years / since 2015).\nWith a finished time (yesterday, in 2010) use the past simple instead."),
 [("Have you ever eaten sushi?", "As-tu déjà mangé des sushis ?", "Have you ever eaten sushi?"), ("He has just arrived.", "Il vient d'arriver.", "He has just arrived.")],
 r"\b(have|has|haven't|hasn't) (?:\w+ )?(?:been|done|seen|gone|eaten|lost|finished|read|lived|made|had|met|heard)\b", ['have', 'has', "haven't", "hasn't"]),
pt('B1', 'modals', ("Obligation et conseil : must, have to, should",
 "« Must » et « have to » expriment l'obligation (You must stop. I have to work). Attention aux négations : mustn't = interdiction, don't have to = ce n'est pas nécessaire.\n« Should » donne un conseil (You should rest). « May » et « might » expriment la possibilité (It might rain).\nLes modaux sont suivis du verbe sans « to » et ne prennent pas de -s."),
 ('Obligation and advice: must, have to, should',
 "“Must” and “have to” express obligation (You must stop. I have to work). Mind the negatives: mustn't = prohibition, don't have to = not necessary.\n“Should” gives advice (You should rest). “May” and “might” express possibility (It might rain).\nModals are followed by the bare verb and take no -s."),
 [("You should see a doctor.", "Tu devrais voir un médecin.", "You should see a doctor."), ("You don't have to come.", "Tu n'es pas obligé de venir.", "You don't have to come.")],
 r"\b(must|should|might|may|shouldn't|mustn't)\b", ['must', 'should', 'might', 'may']),
pt('B1', 'conditional-1', ('Les phrases avec if (réel)',
 "Condition possible : if + présent, will + verbe. If it rains, I will stay at home. On ne met jamais « will » après if.\nVérité générale : if + présent, présent. If you heat ice, it melts.\n« Unless » = if … not ; « when » pour ce qui est certain."),
 ('If-sentences (real conditions)',
 "Possible condition: if + present, will + verb. If it rains, I will stay at home. Never put “will” after if.\nGeneral truth: if + present, present. If you heat ice, it melts.\n“Unless” = if … not; use “when” for what is certain."),
 [("If you study, you will pass.", "Si tu étudies, tu réussiras.", "If you study, you will pass.")],
 r"\b(If|if|unless|Unless)\b", ['if', 'unless', 'when', 'because']),
pt('B1', 'relatives', ('Les relatives : who, which, that',
 "« Who » pour les personnes, « which » pour les choses, « that » pour les deux dans la langue courante. « Whose » = dont (possession), « where » pour un lieu.\nQuand le pronom est complément, on peut le supprimer : the book (that) I read."),
 ('Relative clauses: who, which, that',
 "“Who” for people, “which” for things, “that” for both in everyday speech. “Whose” shows possession, “where” refers to a place.\nWhen the pronoun is the object it can be dropped: the book (that) I read."),
 [("The man who lives next door is a doctor.", "L'homme qui habite à côté est médecin.", "The man who lives next door is a doctor."), ("This is the house where I was born.", "C'est la maison où je suis né.", "This is the house where I was born.")],
 r"\b(who|which|whose|where)\b(?!.*\?)", ['who', 'which', 'whose', 'where']),
pt('B1', 'passive', ('Le passif',
 "be + participe passé : The window was broken. L'agent est introduit par « by » (by a child).\nOn conjugue « be » au temps voulu : is made, was made, has been made, will be made.\nL'anglais emploie le passif bien plus que le français : I was told… = on m'a dit…"),
 ('The passive',
 "be + past participle: The window was broken. The agent is introduced by “by” (by a child).\nConjugate “be” in the tense you need: is made, was made, has been made, will be made.\nEnglish also allows: I was told… / She was given a prize."),
 [("This book was written in 1950.", "Ce livre a été écrit en 1950.", "This book was written in 1950."), ("English is spoken here.", "On parle anglais ici.", "English is spoken here.")],
 r"\b(?:is|are|was|were|been) (written|made|built|born|called|killed|told|given|taken|found|used|sold)\b", None),
pt('B2', 'conditional-2', ("L'irréel : would et would have",
 "Irréel du présent : if + prétérit, would + verbe. If I had more time, I would travel. Avec be, on dit were à toutes les personnes : If I were you…\nIrréel du passé : if + had + participe, would have + participe. If I had known, I would have come.\n« I wish » suit la même logique : I wish I were rich. I wish I had studied."),
 ('Unreal conditions: would and would have',
 "Unreal present: if + past simple, would + verb. If I had more time, I would travel. With be, use were for every person: If I were you…\nUnreal past: if + had + participle, would have + participle. If I had known, I would have come.\n“I wish” follows the same logic: I wish I were rich. I wish I had studied."),
 [("If I were you, I would accept.", "À ta place, j'accepterais.", "If I were you, I would accept."), ("I would have helped if you had asked.", "J'aurais aidé si tu avais demandé.", "I would have helped if you had asked.")],
 r"\b(would|wouldn't)\b", ['would', 'will', 'did', 'had']),
pt('B2', 'gerund-infinitive', ('Verbe en -ing ou infinitif ?',
 "Certains verbes sont suivis de -ing : enjoy, finish, avoid, mind, keep, suggest (I enjoy reading). D'autres de to + verbe : want, decide, hope, need, promise, learn (I want to go).\nAprès une préposition, toujours -ing : before leaving, good at cooking.\nStop doing = arrêter de faire ; stop to do = s'arrêter pour faire. Remember doing = se souvenir d'avoir fait ; remember to do = penser à faire."),
 ('Verb-ing or infinitive?',
 "Some verbs take -ing: enjoy, finish, avoid, mind, keep, suggest (I enjoy reading). Others take to + verb: want, decide, hope, need, promise, learn (I want to go).\nAfter a preposition always use -ing: before leaving, good at cooking.\nStop doing = quit; stop to do = pause in order to do. Remember doing = recall; remember to do = not forget."),
 [("She decided to leave.", "Elle a décidé de partir.", "She decided to leave."), ("I enjoy cooking.", "J'aime cuisiner.", "I enjoy cooking.")],
 r"\b(?:want|wants|wanted|decided|hope|need|needs) (to) \w+", ['to', 'for', 'at', 'of']),
pt('B2', 'reported', ('Le discours indirect',
 "Quand le verbe introducteur est au passé, les temps reculent d'un cran : présent → prétérit (\"I am tired\" → He said he was tired), prétérit → past perfect, will → would, can → could.\n« Say » (dire quelque chose) / « tell » + personne (He told me that…).\nQuestion indirecte : ordre sujet-verbe, sans do : She asked where I lived."),
 ('Reported speech',
 "When the reporting verb is past, tenses shift back: present → past (\"I am tired\" → He said he was tired), past → past perfect, will → would, can → could.\n“Say” something / “tell” + person (He told me that…).\nReported questions keep subject-verb order, with no do: She asked where I lived."),
 [("He said he was busy.", "Il a dit qu'il était occupé.", "He said he was busy."), ("She told me that she would come.", "Elle m'a dit qu'elle viendrait.", "She told me that she would come.")],
 r"\b(said|told|asked)\b", ['said', 'told', 'asked']),
pt('C1', 'inversion', ("L'inversion et l'emphase",
 "Dans un style soutenu, un adverbe négatif en tête de phrase entraîne l'inversion : Never have I seen such a thing. Not only did he come, but he also helped. Hardly had we arrived when it started to rain.\nPour insister sur un élément, on emploie une phrase clivée : It was John who called. What I need is a holiday."),
 ('Inversion and emphasis',
 "In formal style a negative adverb at the start of the sentence triggers inversion: Never have I seen such a thing. Not only did he come, but he also helped. Hardly had we arrived when it started to rain.\nTo stress one element, use a cleft sentence: It was John who called. What I need is a holiday."),
 [("Never have I been so happy.", "Jamais je n'ai été aussi heureux.", "Never have I been so happy.")],
 r"^(Never|Rarely|Seldom|Hardly|Not only) (?:have|has|had|did|do|does|was|is)\b", ['Never', 'Rarely', 'Hardly', 'Not only']),
]
